"""Event creation helper: the single write path for the event table.

The legacy app/events.py writer was deleted with the old schema; payload
validation funnels through app.payloads.
"""
from datetime import date, datetime, time

from sqlalchemy.orm import Session

from .models import Event, Person
from .payloads import validate_event_payload

# event types that are auto-generated by the system; the rest are teacher-defined
SYSTEM_EVENT_TYPES = {
    "birthday",
    "enrolled",
    "class_moved",
    "exam_taken",
    "seat_changed",
}

# event types that teachers write by hand
MANUAL_EVENT_TYPES = {
    "home_visited", "comment",
}

# yearly birthdays are system-managed; calendar/timeline expand them from birth_date
AUTO_RECORD_EVENT_TYPES = {"birthday"}

# everything shown as a 跟进记录/事件 in lists and calendars
RECORD_EVENT_TYPES = MANUAL_EVENT_TYPES | AUTO_RECORD_EVENT_TYPES


def next_birthday_date(birth_date: date, today: date | None = None) -> date:
    """The next occurrence of the given birthday on or after `today`."""
    today = today or date.today()
    for y in (today.year, today.year + 1):
        try:
            cand = date(y, birth_date.month, birth_date.day)
        except ValueError:  # Feb 29 → Feb 28 on non-leap years
            cand = date(y, birth_date.month, 28)
        if cand >= today:
            return cand
    return cand


def birthday_in_month(birth_date: date, year: int, month: int) -> date | None:
    """Return this student's birthday date within the given calendar month."""
    if birth_date.month != month:
        return None
    try:
        return date(year, month, birth_date.day)
    except ValueError:  # Feb 29 → Feb 28 on non-leap years
        if month == 2:
            return date(year, 2, 28)
        return None


def birthday_events_for_student(db: Session, student_id) -> list[Event]:
    return (
        db.query(Event)
        .filter(
            Event.type == "birthday",
            Event.attendees.any(Person.id == student_id),
        )
        .order_by(Event.created_at.asc(), Event.id.asc())
        .all()
    )


def find_birthday_event(db: Session, student_id) -> Event | None:
    rows = birthday_events_for_student(db, student_id)
    return rows[0] if rows else None


def dedupe_birthday_events(db: Session) -> None:
    """Keep at most one birthday Event per student."""
    role = Person.payload["role"].as_string()
    for student in db.query(Person).filter(role == "student").all():
        for duplicate in birthday_events_for_student(db, student.id)[1:]:
            db.delete(duplicate)


def sync_birthday_event(db: Session, student: Person) -> None:
    """Create/update/remove the yearly birthday Event for one student."""
    payload = student.payload or {}
    birth_raw = payload.get("birth_date")
    graduated = bool(payload.get("graduated_at"))
    existing_rows = birthday_events_for_student(db, student.id)
    existing = existing_rows[0] if existing_rows else None
    for duplicate in existing_rows[1:]:
        db.delete(duplicate)

    if not birth_raw or graduated:
        if existing is not None:
            db.delete(existing)
        return

    birth_date = date.fromisoformat(birth_raw)
    start = datetime.combine(next_birthday_date(birth_date), time(9, 0))
    event_payload = validate_event_payload("birthday", {"birth_date": birth_raw})

    if existing is None:
        create_event(
            db,
            event_type="birthday",
            title="生日",
            start_time=start,
            payload=event_payload,
            attendee_ids=[student.id],
        )
        return

    existing.start_time = start
    existing.payload = event_payload


def sync_all_birthday_events(db: Session) -> None:
    dedupe_birthday_events(db)
    role = Person.payload["role"].as_string()
    for student in db.query(Person).filter(role == "student").all():
        sync_birthday_event(db, student)


def create_event(db: Session, *, event_type: str, title: str, start_time: datetime,
                 end_time: datetime | None = None, location: str | None = None,
                 description: str | None = None, payload: dict | None = None,
                 attendee_ids: list | tuple = (), commit: bool = False) -> Event:
    """Single write path for events: validates the payload, links attendees."""
    ev = Event(type=event_type, title=title, start_time=start_time, end_time=end_time,
               location=location, description=description,
               payload=validate_event_payload(event_type, payload))
    if attendee_ids:
        ev.attendees = db.query(Person).filter(Person.id.in_(attendee_ids)).all()
    db.add(ev)
    if commit:
        db.commit()
    return ev
